% Problem: Simulating Repeated-Dose Drug Accumulation Until Steady State
% Name:
% Date:

clear; clc;

dose = 50;
fractionRemaining = 0.4;
numDoses = 6;
threshold = 80;

% a) For-loop: build concHistory over numDoses doses, starting from C = 0


% b) Display concHistory and the concentration after the 6th dose (2 decimals)


% c) While-loop: count doses needed for C to first exceed threshold, starting fresh from C = 0


% d) One-sentence written explanation (as a comment) of why the values level off

solutionCode:
dose = 50;
fractionRemaining = 0.4;
numDoses = 6;
threshold = 80;

% a) For-loop simulation
C = 0;
concHistory = zeros(1, numDoses);
for i = 1:numDoses
    C = C * fractionRemaining + dose;
    concHistory(i) = C;
end

% b) Display results
disp(concHistory)
fprintf('Concentration after dose 6: %.2f\n', concHistory(numDoses));

% c) While-loop to find doses needed to exceed threshold
C = 0;
dosesNeeded = 0;
while C <= threshold
    C = C * fractionRemaining + dose;
    dosesNeeded = dosesNeeded + 1;
end
disp(dosesNeeded)

% d) Written explanation:
% Each new concentration is old_C*fractionRemaining (a shrinking carryover, since
% fractionRemaining < 1) plus a constant 50 mg/L dose, so as old_C grows the carryover
% term approaches a fixed value and the total stops changing much dose to dose --
% it levels off near a steady-state ceiling instead of growing without bound.

