solutionCode:
% a) Single patient
age = 72; TUG = 14.5; hadFallLastYear = true;
riskScore = (age >= 65) + (TUG > 12) + hadFallLastYear;  % logical values add as 1/0
if riskScore >= 2
    riskCategory = 'High Risk';
elseif riskScore == 1
    riskCategory = 'Moderate Risk';
else
    riskCategory = 'Low Risk';
end
fprintf('Single patient: score = %d, %s\n', riskScore, riskCategory);

% b) Clinic of 6 patients
ages = [70 55 81 62 45 90];
TUG  = [11 15.2 9.8 13.1 8.0 16.5];
hadFallLastYear = [true false true false false true];

for i = 1:length(ages)
    riskScore = (ages(i) >= 65) + (TUG(i) > 12) + hadFallLastYear(i);
    if riskScore >= 2
        riskCategory = 'High Risk';
    elseif riskScore == 1
        riskCategory = 'Moderate Risk';
    else
        riskCategory = 'Low Risk';
    end
    fprintf('Patient %d: score = %d, %s\n', i, riskScore, riskCategory);
end

% c) Same loop, classify with switch on riskScore
for i = 1:length(ages)
    riskScore = (ages(i) >= 65) + (TUG(i) > 12) + hadFallLastYear(i);
    switch riskScore
        case 0
            riskCategory = 'Low Risk';
        case 1
            riskCategory = 'Moderate Risk';
        case {2, 3}
            riskCategory = 'High Risk';
    end
    fprintf('Patient %d (switch): score = %d, %s\n', i, riskScore, riskCategory);
end

% d) Vectorized highRisk flag (no loop)
riskScoreAll = (ages >= 65) + (TUG > 12) + hadFallLastYear;
highRisk = riskScoreAll >= 2;
disp(highRisk)
fprintf('Number of high-risk patients: %d\n', sum(highRisk));

% e) Written critique:
% Patient 2 (age 55, TUG = 15.2s, no prior fall) and Patient 4 (age 62, TUG = 13.1s, no
% prior fall) both score 1 and are both labeled "Moderate Risk," even though Patient 2's
% gait speed is meaningfully slower than Patient 4's -- the rule only checks whether TUG
% crosses the single 12-second cutoff, not how far past it a patient falls. Any simple
% additive point rule like this one throws away magnitude information once a threshold is
% crossed, so two patients who are clinically quite different on one measurement can still
% collapse into the same score and the same recommended level of concern.

% f) Proposed change:
